```python
def is_anagram(str1, str2):
    # Ensure both strings are of the same length
    if len(str1) != len(str2):
        return False

    # Create a dictionary to count the frequency of each character in the first string
    char_count = {char: str1.count(char) for char in str1}

    # Decrease the count of each character in the second string
    for char in str2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    # If all counts are 0, the strings are anagrams
    return all(count == 0 for count in char_count.values())

